import React from 'react';
import styled from 'styled-components';
// Şimdilik diğer bileşenleri import etmeyi kaldıralım
// import Hero from '../components/home/Hero';
// import Features from '../components/home/Features';
// import PopularRecipes from '../components/home/PopularRecipes';
// import HowItWorks from '../components/home/HowItWorks';
// import Testimonials from '../components/home/Testimonials';
// import CallToAction from '../components/home/CallToAction';

// Styled components tanımlamaları
const HomeContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const HeroSection = styled.div`
  background-color: #f5f5f5;
  padding: 60px 20px;
  text-align: center;
  border-radius: 8px;
  margin-bottom: 40px;
`;

const HeroTitle = styled.h1`
  color: #4CAF50;
  font-size: 2.5rem;
  margin-bottom: 20px;
`;

const HeroSubtitle = styled.p`
  font-size: 1.2rem;
  color: #555;
  max-width: 700px;
  margin: 0 auto 30px;
`;

const SearchBar = styled.div`
  display: flex;
  max-width: 600px;
  margin: 0 auto;
  
  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const SearchInput = styled.input`
  flex: 1;
  padding: 15px;
  border: 1px solid #ddd;
  border-radius: 4px 0 0 4px;
  font-size: 1rem;
  
  @media (max-width: 768px) {
    border-radius: 4px;
    margin-bottom: 10px;
  }
`;

const SearchButton = styled.button`
  background-color: #FF9800;
  color: white;
  border: none;
  padding: 15px 30px;
  border-radius: 0 4px 4px 0;
  cursor: pointer;
  font-weight: bold;
  
  &:hover {
    background-color: #F57C00;
  }
  
  @media (max-width: 768px) {
    border-radius: 4px;
  }
`;

const SectionTitle = styled.h2`
  color: #333;
  margin-bottom: 20px;
  text-align: center;
  position: relative;
  
  &:after {
    content: '';
    display: block;
    width: 50px;
    height: 3px;
    background-color: #4CAF50;
    margin: 10px auto;
  }
`;

const CategoriesContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 40px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(3, 1fr);
  }
  
  @media (max-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 480px) {
    grid-template-columns: 1fr;
  }
`;

const CategoryCard = styled.div`
  background-color: white;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  
  &:hover {
    transform: translateY(-5px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
  }
`;

const CategoryImage = styled.img`
  width: 100%;
  height: 150px;
  object-fit: cover;
`;

const CategoryContent = styled.div`
  padding: 15px;
  text-align: center;
`;

const CategoryTitle = styled.h3`
  margin-bottom: 5px;
  color: #333;
`;

const CategoryCount = styled.span`
  color: #777;
  font-size: 0.9rem;
`;

const FeaturedRecipesContainer = styled.div`
  margin-bottom: 40px;
`;

const RecipesGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 576px) {
    grid-template-columns: 1fr;
  }
`;

const RecipeCard = styled.div`
  background-color: white;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
`;

const RecipeImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
`;

const RecipeContent = styled.div`
  padding: 15px;
`;

const RecipeTitle = styled.h3`
  margin-bottom: 10px;
  color: #333;
`;

const RecipeMeta = styled.div`
  display: flex;
  justify-content: space-between;
  color: #777;
  font-size: 0.9rem;
  margin-bottom: 10px;
`;

const RecipePrice = styled.div`
  font-weight: bold;
  color: #4CAF50;
  margin-top: 10px;
`;

const HomePage = () => {
  // Örnek kategori verileri
  const categories = [
    { id: 1, title: 'Ana Yemekler', count: 42, image: 'https://via.placeholder.com/300x150?text=Ana+Yemekler' },
    { id: 2, title: 'Çorbalar', count: 18, image: 'https://via.placeholder.com/300x150?text=Çorbalar' },
    { id: 3, title: 'Tatlılar', count: 36, image: 'https://via.placeholder.com/300x150?text=Tatlılar' },
    { id: 4, title: 'Salatalar', count: 24, image: 'https://via.placeholder.com/300x150?text=Salatalar' },
    { id: 5, title: 'Kahvaltılık', count: 15, image: 'https://via.placeholder.com/300x150?text=Kahvaltılık' },
    { id: 6, title: 'Atıştırmalıklar', count: 28, image: 'https://via.placeholder.com/300x150?text=Atıştırmalıklar' },
    { id: 7, title: 'İçecekler', count: 12, image: 'https://via.placeholder.com/300x150?text=İçecekler' },
    { id: 8, title: 'Dünya Mutfağı', count: 31, image: 'https://via.placeholder.com/300x150?text=Dünya+Mutfağı' }
  ];

  // Örnek tarif verileri
  const featuredRecipes = [
    {
      id: 1,
      title: 'Ev Yapımı Lazanya',
      time: '45 dk',
      difficulty: 'Orta',
      image: 'https://via.placeholder.com/300x200?text=Lazanya',
      price: '₺120'
    },
    {
      id: 2,
      title: 'Köfte Patates',
      time: '30 dk',
      difficulty: 'Kolay',
      image: 'https://via.placeholder.com/300x200?text=Köfte+Patates',
      price: '₺85'
    },
    {
      id: 3,
      title: 'Sebzeli Makarna',
      time: '20 dk',
      difficulty: 'Kolay',
      image: 'https://via.placeholder.com/300x200?text=Sebzeli+Makarna',
      price: '₺60'
    }
  ];

  return (
    <HomeContainer>
      <HeroSection>
        <HeroTitle>Ucuz'a Pişir</HeroTitle>
        <HeroSubtitle>
          En uygun fiyatlarla en lezzetli yemekleri pişirmenin yolu.
          Yapay zeka destekli sistemimiz, malzemeleri en uygun fiyatlarla bulmanıza yardımcı olur.
        </HeroSubtitle>
        <SearchBar>
          <SearchInput 
            type="text" 
            placeholder="Hangi yemeği yapmak istiyorsunuz? (ör. Lazanya, Köfte...)" 
          />
          <SearchButton>Tarif Bul</SearchButton>
        </SearchBar>
      </HeroSection>

      <SectionTitle>Yemek Kategorileri</SectionTitle>
      <CategoriesContainer>
        {categories.map(category => (
          <CategoryCard key={category.id}>
            <CategoryImage src={category.image} alt={category.title} />
            <CategoryContent>
              <CategoryTitle>{category.title}</CategoryTitle>
              <CategoryCount>{category.count} tarif</CategoryCount>
            </CategoryContent>
          </CategoryCard>
        ))}
      </CategoriesContainer>

      <FeaturedRecipesContainer>
        <SectionTitle>Öne Çıkan Tarifler</SectionTitle>
        <RecipesGrid>
          {featuredRecipes.map(recipe => (
            <RecipeCard key={recipe.id}>
              <RecipeImage src={recipe.image} alt={recipe.title} />
              <RecipeContent>
                <RecipeTitle>{recipe.title}</RecipeTitle>
                <RecipeMeta>
                  <span>⏱️ {recipe.time}</span>
                  <span>🔥 {recipe.difficulty}</span>
                </RecipeMeta>
                <RecipePrice>Tahmini Maliyet: {recipe.price}</RecipePrice>
              </RecipeContent>
            </RecipeCard>
          ))}
        </RecipesGrid>
      </FeaturedRecipesContainer>
    </HomeContainer>
  );
};

export default HomePage;
